import type { Object3D } from 'three';

export function findPartId(object: Object3D, modelRoot: Object3D, partRoots: Map<Object3D, string>): string | null {
  let current: Object3D | null = object;
  while (current && current !== modelRoot) {
    if (!current.visible) return null;
    const id = partRoots.get(current);
    if (id) return id;
    current = current.parent;
  }
  return null;
}
