import { memo, useEffect, useRef, useState, type ComponentType } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { DeviceConfig } from '../../config/schema';
import { clearAssetCaches } from '../../shared/assetCache';
import { activeScenePalette } from '../../shared/scenePalette';
import { dampingForFrame } from '../../shared/orbitDamping';
import { coarseRotateSpeedScale, detectCoarsePointer } from '../../shared/orbitSpeed';
import { calculateFitDistanceForBounds, getAvailableViewport, getViewDirection } from './deviceCamera';
import { disposeLoadedDeviceModel, loadDeviceModel, type LoadedDeviceModel } from './deviceModel';
import { findPartId } from './devicePicking';
import { applyRuntimeState, buildExplosionMotions, createExplosionSpring, equalizeStackMotions, buildPackingLayout, liftTerminalBounds, shiftPartBounds, stepExplosionSpring, terminalBounds, type DeviceSceneState } from './deviceSceneState';
import { PointerTap } from './pointer-tap';

/**
 * OrbitControls 的基准阻尼系数（60fps 下每帧衰减）。运行时按真实帧长换算成等价的每帧系数，
 * 否则低帧率手机上惯性会被按帧摊成好几秒（见 shared/orbitDamping.ts）。
 */
const DEVICE_DAMPING_BASE = 0.085;

/**
 * 旋转灵敏度基准（OrbitControls 默认 1）。手指设备上按画布高度补偿：
 * 每像素弧度是 `rotateSpeed * 2π / 画布高`，画布越高越钝（见 shared/orbitSpeed.ts）。
 */
const DEVICE_ROTATE_SPEED = 1;

/**
 * 模型加载失败后自动重试的次数（与场地页 `SITE_LOAD_RETRIES` 同一套思路，退避 1.5s / 3s）。
 * 几十 MB 的整包下载在手机网络上偶发中断是常态，不该让用户自己点「重新加载」。
 */
const DEVICE_LOAD_RETRIES = 2;

/**
 * 拆解镜头跟随的阻尼系数：镜头每帧向"当前展开程度对应的取景"逼近的速度。
 * 取 2.4 是"跟拍"而不是"吸附"——展开到底约 1.5s 内收住，跟随过程中与部件运动同呼吸。
 */
const DEVICE_FOLLOW_LAMBDA = 2.4;

/**
 * 展开到底时镜头绕 Y 轴的环绕角度（度）。固定的机位正对一个方向上吊会像"图钉板"，
 * 边拉远边缓慢环绕十几度，部件之间的前后关系才露出来。
 */
const DEVICE_ORBIT_DEGREES = 14;

/** 环绕轴（镜头绕世界 Y 轴缓慢环绕，和 OrbitControls 的极轴一致）。 */
const UP = new THREE.Vector3(0, 1, 0);

export interface DeviceSceneProps {
  device: DeviceConfig;
  state: DeviceSceneState;
  onPartSelect(id: string): void;
  onPartHover?(id: string | null): void;
  onProgress?(percent: number): void;
  onError?(message: string): void;
  retryToken?: number;
}

export type DeviceSceneComponent = ComponentType<DeviceSceneProps>;

function setSelected(model: LoadedDeviceModel, selectedPartId: string | null, selectedEmissive: number) {
  const selectedColor = new THREE.Color(selectedEmissive);
  for (const runtime of model.parts.values()) {
    const selected = runtime.id === selectedPartId;
    for (const mesh of runtime.meshes) {
      const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      for (const material of materials) {
        if (!('emissive' in material) || !(material.emissive instanceof THREE.Color)) continue;
        const data = material.userData as { deviceBaseEmissive?: THREE.Color; deviceBaseIntensity?: number };
        if (!data.deviceBaseEmissive) {
          data.deviceBaseEmissive = material.emissive.clone();
          data.deviceBaseIntensity = 'emissiveIntensity' in material && typeof material.emissiveIntensity === 'number' ? material.emissiveIntensity : 1;
        }
        material.emissive.copy(selected ? selectedColor : data.deviceBaseEmissive);
        if ('emissiveIntensity' in material && typeof material.emissiveIntensity === 'number') {
          material.emissiveIntensity = selected ? 0.85 : (data.deviceBaseIntensity ?? 1);
        }
      }
    }
  }
}

export const DeviceScene = memo(function DeviceScene({
  device,
  state,
  onPartSelect,
  onPartHover,
  onProgress,
  onError,
  retryToken = 0,
}: DeviceSceneProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const latestRef = useRef(state);
  const selectRef = useRef(onPartSelect);
  const hoverRef = useRef(onPartHover);
  const progressRef = useRef(onProgress);
  const errorRef = useRef(onError);
  const [progress, setProgress] = useState(0);
  const [issueCount, setIssueCount] = useState(0);
  const [loadError, setLoadError] = useState('');
  const [contextPaused, setContextPaused] = useState(false);
  const [contextReason, setContextReason] = useState('');
  const [retryAttempt, setRetryAttempt] = useState(0);

  latestRef.current = state;
  selectRef.current = onPartSelect;
  hoverRef.current = onPartHover;
  progressRef.current = onProgress;
  errorRef.current = onError;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    let disposed = false;
    let animationFrame = 0;
    let dirty = true;
    let ready = false;
    let loadedModel: LoadedDeviceModel | null = null;
    let renderedStateKey = '';
    let renderedSelectionKey = '';
    let lastView = '';
    let lastReset = -1;
    let lastIsolateKey = '';
    let explosionAmount = 0;
    // 拆解进度用弹簧平滑（见 stepExplosionSpring）：起步有加速、末段一点点回弹。
    const explosionSpring = createExplosionSpring();
    let contextIsLost = false;
    let restoreFallback = 0;
    // 加载失败自动重试的次数（与场地页同一套思路）：模型是几十 MB 的整包下载，
    // 手机网络与 GitHub Pages 偶发中断不值得让用户手动点「重新加载」。
    let autoRetry = 0;
    let retryTimer = 0;
    // 编排拆解（grouped 模式）一次计算，拆解期间不复算；null 表示用旧逻辑。
    // 模型加载后会被等距化（见 equalizeStackMotions），所以这里不能是 const。
    let explosionMotions = buildExplosionMotions(device);
    // B 阶段装箱布局与展开终态包围盒：模型加载并居中后计算一次。
    // frustum 两套取景：装配态用模型当前包围盒，展开态用装箱终态包围盒。
    let packingLayout: ReturnType<typeof buildPackingLayout> = null;
    let layoutTarget: THREE.Box3 | null = null;
    let layoutFraming = false;
    // 装配态包围盒在模型加载完成、任何拆解位移发生之前抓一次（之后模型根节点自己会动，
    // currentBounds() 量到的是"正在展开"的盒子，不能当基准）。
    let assemblyTarget: THREE.Box3 | null = null;
    // 用户上一次亲手操作镜头的时间戳：跟拍只在"没人接管镜头"时进行。
    let lastManualAt = 0;
    // 跟拍已经环绕到的角度（按 eased 记），以及上一帧镜头离目标机位还差多远。
    let choreographEased = 0;
    let cameraResidual = 0;
    // 跟拍锁：展开量一动就锁上，镜头走到位或用户接手才松开（避免"动画停了镜头还在飘"，
    // 也避免装配态下用户自己缩放后镜头又被拽回取景距离）。
    let cameraChasing = false;
    const clock = new THREE.Clock();
    // 舞台配色统一走 activeScenePalette()（precision 的纸面舞台配色见 shared/scenePalette.ts）。
    const palette = activeScenePalette();

    setProgress(0);
    setIssueCount(0);
    setLoadError('');
    setContextPaused(false);

    // 编号牌浮层：部件序号（与左侧目录的行号一一对应）投影到屏幕上，拆解时才显出来。
    // 画在 WebGL 之上、不接指针事件，所以不挡拾取/拖拽。
    const labelLayer = document.createElement('div');
    labelLayer.className = 'device-part-labels';
    let labelsHidden = false;
    const labels: { node: HTMLSpanElement; root: THREE.Object3D; world: THREE.Vector3 }[] = [];

    let renderer: THREE.WebGLRenderer;
    try {
      // MSAA raises GPU load enough to trigger WebGL context loss on some
      // desktops (notably virtualized/remote display stacks). Disable it and cap
      // pixel ratio below — visually negligible on high-DPI screens.
      renderer = new THREE.WebGLRenderer({ antialias: false, alpha: false, powerPreference: 'high-performance' });
    } catch {
      const message = '无法启动三维查看器，请使用支持 WebGL 的浏览器';
      setLoadError(message);
      errorRef.current?.(message);
      return;
    }

    renderer.setClearColor(palette.device.clearColor, 1);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = palette.device.exposure;
    renderer.domElement.setAttribute('aria-label', '交互式三维设备模型。拖动旋转，滚轮或双指缩放，点击部件查看详情。');
    host.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(35, 1, 0.01, 500);
    const controls = new OrbitControls(camera, renderer.domElement);
    camera.position.fromArray(device.camera.position);
    controls.target.fromArray(device.camera.target);
    controls.enableDamping = true;
    controls.dampingFactor = DEVICE_DAMPING_BASE;
    controls.rotateSpeed = DEVICE_ROTATE_SPEED;
    controls.enablePan = false;
    controls.minDistance = device.camera.minDistance;
    controls.maxDistance = device.camera.maxDistance;
    controls.maxPolarAngle = Math.PI * 0.96;
    controls.addEventListener('change', () => { dirty = true; });

    const pmrem = new THREE.PMREMGenerator(renderer);
    const room = new RoomEnvironment();
    const environment = pmrem.fromScene(room, 0.04);
    scene.environment = environment.texture;
    // IBL 是舞台亮度的主导项（RoomEnvironment 是个明亮的白色房间）：
    // 只压方向光会留下一片中灰地面，必须按配色压 IBL 强度。
    scene.environmentIntensity = palette.device.environmentIntensity;
    room.dispose();
    pmrem.dispose();
    scene.add(new THREE.HemisphereLight(palette.device.hemisphere.sky, palette.device.hemisphere.ground, palette.device.hemisphere.intensity));
    const keyLight = new THREE.DirectionalLight(palette.device.key.color, palette.device.key.intensity);
    keyLight.position.set(...palette.device.key.position);
    scene.add(keyLight);
    const rimLight = new THREE.DirectionalLight(palette.device.rim.color, palette.device.rim.intensity);
    rimLight.position.set(...palette.device.rim.position);
    scene.add(rimLight);

    const groundMaterial = new THREE.MeshStandardMaterial({ color: palette.device.ground.color, roughness: palette.device.ground.roughness });
    const platformMaterial = new THREE.MeshStandardMaterial({ color: palette.device.platform.color, metalness: palette.device.platform.metalness, roughness: palette.device.platform.roughness });
    const ringMaterial = new THREE.MeshBasicMaterial({ color: palette.device.ring.color, transparent: true, opacity: palette.device.ring.opacity, side: THREE.DoubleSide });
    const innerRingMaterial = new THREE.MeshBasicMaterial({ color: palette.device.innerRing.color, transparent: true, opacity: palette.device.innerRing.opacity, side: THREE.DoubleSide });
    const ground = new THREE.Mesh(new THREE.CircleGeometry(80, 96), groundMaterial);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -2.735;
    scene.add(ground);
    const platform = new THREE.Mesh(new THREE.CylinderGeometry(2.35, 2.42, 0.09, 100), platformMaterial);
    platform.position.y = -2.71;
    scene.add(platform);
    const ring = new THREE.Mesh(new THREE.RingGeometry(2.05, 2.065, 128), ringMaterial);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = -2.66;
    scene.add(ring);
    const innerRing = new THREE.Mesh(new THREE.RingGeometry(1.75, 1.76, 128), innerRingMaterial);
    innerRing.rotation.x = -Math.PI / 2;
    innerRing.position.y = -2.66;
    scene.add(innerRing);

    const modelRoot = new THREE.Group();
    modelRoot.name = 'device-root';
    scene.add(modelRoot);

    const partRoots = new Map<THREE.Object3D, string>();
    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();
    const tap = new PointerTap();

    const currentBounds = (isolatedPartId: string | null) => {
      const bounds = new THREE.Box3();
      if (!loadedModel) return bounds;
      if (isolatedPartId) {
        const runtime = loadedModel.parts.get(isolatedPartId);
        runtime?.roots.forEach(root => bounds.expandByObject(root, true));
      } else {
        bounds.setFromObject(modelRoot);
      }
      return bounds;
    };

    const fit = (isolatedPartId: string | null) => {
      // 展开态按"装箱终态包围盒"取景，否则部件铺开后必然跑出画面；
      // 回归装配态时再取景回当前装配包围盒。两者都是静态包围盒，
      // 因此只在跨越 50% 时切换，不会和用户的缩放/旋转打架。
      const bounds = !isolatedPartId && layoutFraming && layoutTarget
        ? layoutTarget
        : currentBounds(isolatedPartId);
      if (bounds.isEmpty()) {
        camera.clearViewOffset();
        camera.position.fromArray(device.camera.position);
        controls.target.fromArray(device.camera.target);
        controls.update();
        dirty = true;
        return;
      }
      const center = bounds.getCenter(new THREE.Vector3());
      const width = Math.max(1, host.clientWidth);
      const height = Math.max(1, host.clientHeight);
      const viewport = getAvailableViewport({ width, height, detailsOpen: isolatedPartId !== null || latestRef.current.detailsOpen });
      if (isolatedPartId || latestRef.current.detailsOpen) {
        camera.setViewOffset(width, height, width / 2 - (viewport.left + viewport.right) / 2, height / 2 - (viewport.top + viewport.bottom) / 2, width, height);
      } else {
        camera.clearViewOffset();
      }
      const viewDirection = getViewDirection(latestRef.current.view);
      const distance = Math.max(0.1, calculateFitDistanceForBounds(bounds, viewDirection, viewport, camera.fov, camera.aspect, {
        canvas: { width, height },
        // 展开态的部件会铺到四边：取景必须落在上下浮层没盖住的那块里，否则最外沿会钻到
        // 标题/拆解坞底下（实测"十级塔节拉开 + 框架吊到旁边"时四边贴边）。
        respectOverlays: !isolatedPartId && layoutFraming,
      }));
      controls.target.copy(center);
      camera.position.copy(center).addScaledVector(viewDirection, distance);
      controls.minDistance = Math.min(device.camera.minDistance, Math.max(0.05, distance * 0.15));
      controls.maxDistance = Math.max(device.camera.maxDistance, distance * 4);
      controls.update();
      dirty = true;
    };

    /**
     * 拆解镜头编排（方案三）：镜头跟着"当前展开程度对应的包围盒"连续后撤，并随展开缓速环绕。
     *
     * 与 fit() 的区别是"连续 + 阻尼"，不是切机位：这里不改任何离散状态，也不认死某个方位角——
     * 拉远是沿着**用户当前视线的方向**做的（只改距离、只把注视点挪向包围盒中心），
     * 所以它不会跟手动旋转/滚轮打架，也不会把「前视图」按钮拧歪。
     * 环绕按展开量的**增量**累加（orbitStep），一步步挪过去，用户随时接管都不突兀。
     * 返回本帧开始时镜头离目标机位的距离，用来判断跟拍是否收住。
     */
    const frameScratch = new THREE.Box3();
    const choreograph = (eased: number, delta: number) => {
      if (!assemblyTarget || !layoutTarget || assemblyTarget.isEmpty() || layoutTarget.isEmpty()) return 0;
      frameScratch.min.copy(assemblyTarget.min).lerp(layoutTarget.min, eased);
      frameScratch.max.copy(assemblyTarget.max).lerp(layoutTarget.max, eased);
      const center = frameScratch.getCenter(new THREE.Vector3());
      const width = Math.max(1, host.clientWidth);
      const height = Math.max(1, host.clientHeight);
      const viewport = getAvailableViewport({ width, height, detailsOpen: latestRef.current.detailsOpen });
      // 视线方向取相机当前实际方向：用户自己转过的角度要保留，取景按钮设的前视图也要保留。
      const offset = camera.position.clone().sub(controls.target);
      const offsetLength = offset.length() || 1;
      const direction = offset.divideScalar(offsetLength);
      const orbitStep = (eased - choreographEased) * DEVICE_ORBIT_DEGREES;
      choreographEased = eased;
      if (Math.abs(orbitStep) > 1e-4) direction.applyAxisAngle(UP, THREE.MathUtils.degToRad(orbitStep));
      const distance = Math.max(0.1, calculateFitDistanceForBounds(frameScratch, direction, viewport, camera.fov, camera.aspect, {
        canvas: { width, height },
        // 展开态部件会铺到四边：取景必须落在浮层没盖住的那块里（实测四边贴边）。
        respectOverlays: true,
      }));
      const lambda = DEVICE_FOLLOW_LAMBDA;
      controls.target.x = THREE.MathUtils.damp(controls.target.x, center.x, lambda, delta);
      controls.target.y = THREE.MathUtils.damp(controls.target.y, center.y, lambda, delta);
      controls.target.z = THREE.MathUtils.damp(controls.target.z, center.z, lambda, delta);
      const want = center.clone().addScaledVector(direction, distance);
      const residual = camera.position.distanceTo(want);
      camera.position.x = THREE.MathUtils.damp(camera.position.x, want.x, lambda, delta);
      camera.position.y = THREE.MathUtils.damp(camera.position.y, want.y, lambda, delta);
      camera.position.z = THREE.MathUtils.damp(camera.position.z, want.z, lambda, delta);
      controls.minDistance = Math.min(device.camera.minDistance, Math.max(0.05, distance * 0.15));
      controls.maxDistance = Math.max(device.camera.maxDistance, distance * 4);
      dirty = true;
      return residual;
    };

    const labelForward = new THREE.Vector3();
    const labelProjection = new THREE.Vector3();
    /** 把部件根节点的世界位置投影到屏幕，摆编号牌；相机背后的先按视线方向剔掉。 */
    const updateLabels = (alpha: number) => {
      if (labels.length === 0) return;
      if (alpha <= 0.01) {
        if (labelsHidden) return;
        labelsHidden = true;
        labelLayer.style.display = 'none';
        return;
      }
      if (labelsHidden) {
        labelsHidden = false;
        labelLayer.style.display = '';
      }
      const width = Math.max(1, host.clientWidth);
      const height = Math.max(1, host.clientHeight);
      const opacity = alpha.toFixed(2);
      camera.getWorldDirection(labelForward);
      for (const label of labels) {
        label.root.getWorldPosition(label.world);
        labelProjection.copy(label.world).sub(camera.position);
        if (!label.root.visible || labelProjection.dot(labelForward) <= 0) {
          label.node.style.opacity = '0';
          continue;
        }
        labelProjection.copy(label.world).project(camera);
        const x = (labelProjection.x * 0.5 + 0.5) * width;
        const y = (-labelProjection.y * 0.5 + 0.5) * height;
        label.node.style.transform = `translate(-50%, -50%) translate(${x.toFixed(1)}px, ${y.toFixed(1)}px)`;
        label.node.style.opacity = opacity;
      }
    };

    const pickPart = (clientX: number, clientY: number) => {
      if (!ready || !loadedModel?.parts.size) return null;
      const rect = renderer.domElement.getBoundingClientRect();
      pointer.set((clientX - rect.left) / rect.width * 2 - 1, -(clientY - rect.top) / rect.height * 2 + 1);
      raycaster.setFromCamera(pointer, camera);
      for (const hit of raycaster.intersectObject(modelRoot, true)) {
        const id = findPartId(hit.object, modelRoot, partRoots);
        if (id) return id;
      }
      return null;
    };

    // 用户一碰镜头（拖拽/滚轮）就交还控制权：跟拍立刻松锁，不在他手上抢镜头。
    const takeCameraControl = () => {
      lastManualAt = performance.now();
      cameraChasing = false;
    };
    const pointerDown = (event: PointerEvent) => {
      takeCameraControl();
      tap.down(event.pointerId, event.clientX, event.clientY, event.pointerType === 'touch' ? 12 : 5);
    };
    let lastHoverPick = 0;
    let lastHoverId: string | null = null;
    const pointerMove = (event: PointerEvent) => {
      if (event.buttons !== 0) takeCameraControl();
      tap.move(event.pointerId, event.clientX, event.clientY);
      if (event.pointerType === 'touch' || event.buttons !== 0) return;
      const now = performance.now();
      // Throttle hover raycasts: a full-model raycast is ~13 ms, and firing it
      // on every pointermove saturates the main thread on heavy models.
      if (now - lastHoverPick < 80) return;
      lastHoverPick = now;
      lastHoverId = pickPart(event.clientX, event.clientY);
      hoverRef.current?.(lastHoverId);
      renderer.domElement.style.cursor = lastHoverId ? 'pointer' : 'grab';
    };
    const pointerUp = (event: PointerEvent) => {
      if (!tap.up(event.pointerId, event.clientX, event.clientY)) return;
      const id = pickPart(event.clientX, event.clientY);
      if (id) selectRef.current(id);
    };
    const pointerCancel = (event: PointerEvent) => tap.cancel(event.pointerId);
    const pointerLeave = () => hoverRef.current?.(null);
    renderer.domElement.addEventListener('pointerdown', pointerDown);
    renderer.domElement.addEventListener('pointermove', pointerMove);
    renderer.domElement.addEventListener('pointerup', pointerUp);
    renderer.domElement.addEventListener('pointercancel', pointerCancel);
    renderer.domElement.addEventListener('pointerleave', pointerLeave);
    // 滚轮缩放同样算"用户接管"（OrbitControls 自己监听 wheel，这里只记时间戳）。
    renderer.domElement.addEventListener('wheel', takeCameraControl, { passive: true });

    const contextLost = (event: Event) => {
      event.preventDefault();
      const statusMessage = (event as WebGLContextEvent).statusMessage;
      contextIsLost = true;
      setContextPaused(true);
      setContextReason(statusMessage || '未知原因');
      renderer.domElement.style.opacity = '0';
      if (statusMessage) console.error('WebGL context lost:', statusMessage);
      // Some browsers (notably fragile GPU/VM stacks) never dispatch
      // webglcontextrestored after a loss. Mirror useWebGLContextRecovery:
      // if the context has not come back within a short grace period, rebuild
      // the renderer so the session is not stuck on the pause message forever.
      if (restoreFallback === 0) {
        restoreFallback = window.setTimeout(() => {
          restoreFallback = 0;
          if (disposed) return;
          contextIsLost = false;
          setContextPaused(false);
          setContextReason('');
          setRetryAttempt(value => value + 1);
        }, 600);
      }
    };
    const contextRestored = () => {
      contextIsLost = false;
      if (restoreFallback !== 0) {
        window.clearTimeout(restoreFallback);
        restoreFallback = 0;
      }
      // A lost WebGL context invalidates all buffers/textures; three.js does not
      // re-upload them automatically, so rebuild the renderer and reload the
      // model instead of just un-hiding the (now blank) canvas.
      setContextPaused(false);
      setContextReason('');
      setRetryAttempt(value => value + 1);
    };
    renderer.domElement.addEventListener('webglcontextlost', contextLost);
    renderer.domElement.addEventListener('webglcontextrestored', contextRestored);

    const coarsePointer = detectCoarsePointer();
    // 与场地页同一条取舍（见 SiteScene 的 maxPixelRatio）：手机 GPU 的瓶颈是几何/提交而不是像素，
    // 把手指设备的分辨率锁在 1（画布约 0.33 Mpx，不到 DPR1.5 的 45%），换来的是更稳的帧率，
    // 几何一件不少，所以不会有"部件忽然消失"的跳变。
    const maxPixelRatio = Math.min(window.devicePixelRatio, 1.5);
    const resize = () => {
      if (!host.clientWidth || !host.clientHeight) return;
      renderer.setPixelRatio(coarsePointer ? Math.min(maxPixelRatio, 1) : maxPixelRatio);
      camera.aspect = host.clientWidth / host.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(host.clientWidth, host.clientHeight);
      // 手指设备按画布高度补回桌面旋转手感（画布矮于基准时不缩小，见 shared/orbitSpeed.ts）。
      controls.rotateSpeed = DEVICE_ROTATE_SPEED * coarseRotateSpeedScale(host.clientHeight, coarsePointer);
      if (ready) fit(latestRef.current.isolatedPartId);
      dirty = true;
    };
    const observer = new ResizeObserver(resize);
    observer.observe(host);
    resize();

    loadDeviceModel(device, {
      onProgress: value => {
        if (disposed) return;
        setProgress(value);
        progressRef.current?.(value);
      },
    }).then(model => {
      if (disposed) {
        disposeLoadedDeviceModel(model);
        return;
      }
      loadedModel = model;
      modelRoot.add(model.root);
      // Precompute bounding spheres so the first hover/tap raycast is not a
      // one-time stall (three.js otherwise computes them lazily on first pick).
      modelRoot.traverse(object => { const mesh = object as THREE.Mesh; if (mesh.isMesh) mesh.geometry.computeBoundingSphere(); });
      // Center the model on the turntable: shift its world bounds so the
      // horizontal (X/Z) center sits at the platform origin. Vertical placement
      // is handled below by resting the model's base on the platform top.
      const rawBounds = new THREE.Box3().setFromObject(modelRoot);
      if (!rawBounds.isEmpty()) {
        const rawCenter = rawBounds.getCenter(new THREE.Vector3());
        model.root.position.x -= rawCenter.x;
        model.root.position.z -= rawCenter.z;
        model.root.updateMatrixWorld(true);
        // 部件包围盒是"居中之前"算的：同步平移，否则装箱/起吊终态取景会把相机对到空处。
        shiftPartBounds(model.parts, new THREE.Vector3(-rawCenter.x, 0, -rawCenter.z));
      }
      for (const runtime of model.parts.values()) runtime.roots.forEach(root => partRoots.set(root, runtime.id));
      // 编号牌：号码取部件在配置里的次序（与目录行号一致），锚点是部件根节点的世界位置。
      labels.length = 0;
      labelLayer.replaceChildren();
      device.parts.forEach((part, index) => {
        const runtime = model.parts.get(part.id);
        const root = runtime?.roots[0];
        if (!root) return;
        const node = document.createElement('span');
        node.className = 'device-part-label';
        node.textContent = String(index + 1);
        node.dataset.partId = part.id;
        labelLayer.appendChild(node);
        labels.push({ node, root, world: new THREE.Vector3() });
      });
      renderer.domElement.after(labelLayer);
      const modelBounds = new THREE.Box3().setFromObject(modelRoot);
      if (!modelBounds.isEmpty()) {
        const modelSize = modelBounds.getSize(new THREE.Vector3());
        const footprint = Math.max(modelSize.x, modelSize.z, 1);
        const platformScale = Math.max(0.45, footprint / 4.25);
        const floorY = modelBounds.min.y;
        platform.scale.set(platformScale, 1, platformScale);
        ring.scale.set(platformScale, platformScale, 1);
        innerRing.scale.set(platformScale, platformScale, 1);
        ground.position.y = floorY - 0.075;
        platform.position.y = floorY - 0.045;
        ring.position.y = floorY + 0.006;
        innerRing.position.y = floorY + 0.006;
      }
      setIssueCount(model.issues.length);
      // 同向的一摞部件（发生器塔节）按运行时厚度重排间距：配置里的 distance 只作起点。
      explosionMotions = equalizeStackMotions(model.parts, explosionMotions);
      // B 阶段装箱布局：必须在装配状态下按真实包围盒计算，且要在模型居中之后
      // （居中会改写 model.root.position，影响部件的世界包围盒与挂点旋转）。
      // grouped 模式自带编排，可用 explosion.layout: "none" 关闭装箱。
      if (device.explosion?.layout !== 'none') {
        packingLayout = buildPackingLayout(model.parts);
        layoutTarget = terminalBounds(model.parts, packingLayout);
      } else {
        // 只起吊不装箱（例如塔式设备"逐级向上分离"）：终态包围盒按各自的起吊方向/距离算，
        // 否则吊起来的部件会飞出画面。
        packingLayout = null;
        layoutTarget = liftTerminalBounds(model.parts, explosionMotions);
      }
      ready = true;
      renderedStateKey = '';
      renderedSelectionKey = '';
      layoutFraming = false;
      // 装配态包围盒：此刻部件都还在装配位置（还没写过任何拆解位移），是跟拍插值的起点。
      assemblyTarget = new THREE.Box3().setFromObject(modelRoot);
      fit(latestRef.current.isolatedPartId);
      dirty = true;
    }).catch(error => {
      if (disposed) return;
      const message = error instanceof Error ? error.message : '三维模型加载失败';
      // 弱网/代理中断、缓存里躺着一份坏字节都会让这次加载失败；失败发生在传输阶段，
      // 重试成本低，所以自动再试两次（1.5s / 3s 递增退避）再报错。
      // 重试前清掉模型缓存：坏条目（URL 带版本号、永不变）不扔就永远命中它。
      if (autoRetry < DEVICE_LOAD_RETRIES) {
        autoRetry += 1;
        void clearAssetCaches();
        retryTimer = window.setTimeout(() => {
          retryTimer = 0;
          if (!disposed) setRetryAttempt(value => value + 1);
        }, 1500 * autoRetry);
        return;
      }
      setLoadError(message);
      errorRef.current?.(message);
    });

    // 拆解调试探针（只有 `?perf=1` 时挂载，与 SiteScene 的 `__museumSite` 同一开关）：
    // 量各部件在装配态/展开态的真实世界坐标与相机距离，用来定等距化间距与取景。
    if (new URLSearchParams(window.location.search).get('perf') === '1') {
      (window as unknown as { __museumDevice?: unknown }).__museumDevice = {
        renderer,
        scene,
        camera,
        controls,
        explode: () => explosionAmount,
        cameraDistance: () => camera.position.distanceTo(controls.target),
        parts: () =>
          [...(loadedModel?.parts.values() ?? [])].map(runtime => ({
            id: runtime.id,
            roots: runtime.roots.map(root => {
              const world = new THREE.Vector3();
              root.getWorldPosition(world);
              const box = new THREE.Box3().setFromObject(root);
              const size = new THREE.Vector3();
              box.getSize(size);
              return {
                size: size.toArray(),
                box: [...box.min.toArray(), ...box.max.toArray()],
                local: root.position.toArray(),
                world: world.toArray(),
                visible: root.visible,
                parentWorld: root.parent ? root.parent.getWorldQuaternion(new THREE.Quaternion()).toArray() : null,
                ownWorld: root.getWorldQuaternion(new THREE.Quaternion()).toArray(),
              };
            }),
          })),
      };
    }

    const animate = () => {
      if (disposed) return;
      animationFrame = requestAnimationFrame(animate);
      // While the WebGL context is lost, the canvas is hidden and rendering into
      // the dead context only spams GPU warnings. Wait for the restore/fallback
      // path (below) to tear this effect down and recreate the renderer.
      if (contextIsLost) return;
      // 切到底部导航其它栏目时本页仍然挂载（模型与拆解进度都保留），但外层槽位被
      // hidden 折叠成 0×0：这一帧直接跳过，别在看不见的画布上白渲染。
      if (!host.clientWidth || !host.clientHeight) return;
      const frameSeconds = clock.getDelta();
      const delta = Math.min(frameSeconds, 0.05);
      const stateNow = latestRef.current;
      const nextExplosion = stepExplosionSpring(explosionSpring, stateNow.explode, stateNow.isolatedPartId, delta);
      const explosionMoving = Math.abs(nextExplosion - explosionAmount) > 0.0001;
      explosionAmount = nextExplosion;
      const stateKey = `${stateNow.isolatedPartId}:${stateNow.hiddenPartIds.join(',')}:${explosionAmount.toFixed(4)}`;
      if (ready && loadedModel && stateKey !== renderedStateKey) {
        applyRuntimeState(loadedModel.parts, { ...stateNow, explode: explosionAmount }, explosionMotions, packingLayout);
        renderedStateKey = stateKey;
        dirty = true;
      }
      // 取景档位只作为一个标记保留（fit() 用它决定量哪套包围盒、部件是否铺开），
      // 真正的"拉开"由下面的跟拍连续完成，不再在跨越那一帧硬切机位。
      // 阈值取 0.15 而不是 0.5：塔式设备"逐级上吊"时部件在 50% 就已经升到装配包围盒之外。
      if (ready && loadedModel && layoutTarget) {
        layoutFraming = !stateNow.isolatedPartId && explosionAmount > 0.15;
        // 展开量一动就上跟拍锁；镜头走到位（或用户接管）才松开。
        if (explosionMoving) cameraChasing = true;
        const manual = performance.now() - lastManualAt < 250;
        if (cameraChasing && !manual && !stateNow.isolatedPartId) {
          const eased = explosionAmount * explosionAmount * (3 - 2 * explosionAmount);
          cameraResidual = choreograph(eased, delta);
          if (cameraResidual < 0.02) cameraChasing = false;
        } else {
          // 不跟拍时同步相位，免得下次接手时镜头突然从旧角度甩过来。
          choreographEased = explosionAmount * explosionAmount * (3 - 2 * explosionAmount);
          cameraResidual = 0;
        }
      }
      // Selection highlight only needs to update when the selection changes —
      // not on every explosion frame. Keeping the emissive copy out of the
      // per-frame loop reduces GPU uniform churn during disassembly.
      const selectionKey = `${stateNow.selectedPartId}`;
      if (ready && loadedModel && selectionKey !== renderedSelectionKey) {
        setSelected(loadedModel, stateNow.selectedPartId, palette.device.selectedEmissive);
        renderedSelectionKey = selectionKey;
      }
      if (ready && (stateNow.view !== lastView || stateNow.reset !== lastReset)) {
        lastView = stateNow.view;
        lastReset = stateNow.reset;
        fit(stateNow.isolatedPartId);
      }
      const isolateKey = `${stateNow.isolatedPartId}:${stateNow.detailsOpen}:${stateNow.reset}:${camera.aspect.toFixed(3)}`;
      if (ready && isolateKey !== lastIsolateKey) {
        lastIsolateKey = isolateKey;
        fit(stateNow.isolatedPartId);
      }
      ground.visible = platform.visible = ring.visible = innerRing.visible = !stateNow.isolatedPartId && explosionAmount < 0.5;
      controls.autoRotate = stateNow.rotate && !stateNow.isolatedPartId && explosionAmount < 0.05;
      controls.autoRotateSpeed = 0.65;
      // 惯性衰减按帧算，低帧率手机上会拖成好几秒（见 shared/orbitDamping.ts）。
      // 传未截断的 `frameSeconds`，否则低帧率下会少补一半。
      controls.dampingFactor = dampingForFrame(DEVICE_DAMPING_BASE, frameSeconds);
      controls.update();
      // 编号牌随拆解淡入（0.18→0.40 之间渐显）：装配态不显，免得糊在设备表面。
      updateLabels(stateNow.isolatedPartId ? 0 : Math.max(0, Math.min(1, (explosionAmount - 0.18) / 0.22)));
      if (controls.autoRotate || explosionMoving) dirty = true;
      if (dirty) {
        renderer.render(scene, camera);
        dirty = false;
      }
    };
    animate();

    return () => {
      disposed = true;
      cancelAnimationFrame(animationFrame);
      if (restoreFallback !== 0) window.clearTimeout(restoreFallback);
      if (retryTimer) window.clearTimeout(retryTimer);
      observer.disconnect();
      controls.dispose();
      renderer.domElement.removeEventListener('pointerdown', pointerDown);
      renderer.domElement.removeEventListener('pointermove', pointerMove);
      renderer.domElement.removeEventListener('pointerup', pointerUp);
      renderer.domElement.removeEventListener('pointercancel', pointerCancel);
      renderer.domElement.removeEventListener('pointerleave', pointerLeave);
      renderer.domElement.removeEventListener('wheel', takeCameraControl);
      renderer.domElement.removeEventListener('webglcontextlost', contextLost);
      renderer.domElement.removeEventListener('webglcontextrestored', contextRestored);
      if (loadedModel) disposeLoadedDeviceModel(loadedModel);
      ground.geometry.dispose();
      platform.geometry.dispose();
      ring.geometry.dispose();
      innerRing.geometry.dispose();
      groundMaterial.dispose();
      platformMaterial.dispose();
      ringMaterial.dispose();
      innerRingMaterial.dispose();
      environment.dispose();
      renderer.dispose();
      renderer.domElement.remove();
      labelLayer.remove();
    };
  }, [device, retryAttempt, retryToken]);

  return (
    <div className="device-scene" ref={hostRef}>
      {progress < 100 && !loadError && <div className="device-loading" role="status"><strong>正在准备{device.name}</strong><span>{progress}%</span></div>}
      {issueCount > 0 && <div className="device-diagnostic" role="status">{issueCount} 个模型节点未匹配，其余部件仍可使用</div>}
      {contextPaused && <div className="device-error" role="alert">三维会话已暂停，浏览器恢复后将继续显示{contextReason ? `（原因：${contextReason}）` : ''}</div>}
      {loadError && (
        <div className="device-error device-load-error" role="alert">
          {device.poster && <img src={resolveAssetUrl(device.poster)} alt="" />}
          <strong>模型加载失败</strong>
          <span>{loadError}</span>
          <button
            type="button"
            onClick={() => {
              // 先清掉本应用的 Cache Storage（模型缓存 + 发布包 SW 的内容缓存）再重试：
              // 线上出现过"缓存里躺着一份被截断的模型字节"，不清就永远命中它、点了也没用。
              void clearAssetCaches().finally(() => setRetryAttempt(value => value + 1));
            }}
          >
            重新加载
          </button>
        </div>
      )}
    </div>
  );
});
