import { Box3, Quaternion, Vector3 } from 'three';
import type { DevicePartConfig } from '../../config/schema';

/**
 * 有逻辑的拆解编排（可选 grouped 模式；不启用时完全保持旧的单部件同时散开行为）。
 *
 * grouped 模式提供三层“逻辑”：
 * 1. 组（子装配）：同 `group` 的部件视为一个整体，在同一个时间窗内一起移动；
 *    未标注 group 的部件各自成组。
 * 2. 波次：按 `order` 把各组的窗口均分到 [0,1] 时间轴（由外到内时，外壳先让位、
 *    内部件后动），同一时刻只有少数组在移动，避免所有部件同时四散。
 * 3. 方向规整：显式配置过 direction 的部件保留其方向；未配置（零向量）的部件
 *    自动按水平 360° 扇区取方向，避免部件挤向同一点。distance 缺省按组内序号递增。
 *
 * 计算纯数学、可单测；不读取真实场景与几何。
 */

export interface GroupedExplosionOptions {
  /** 由外到内（外壳先让位）或由内到外。缺省：由外到内。 */
  order?: 'outside-in' | 'inside-out';
  /**
   * true(缺省)：整组刚体同窗移动——同组每个部件在相同窗口内以组方向整体平移，
   * 观感是“一个子装配被整体移开”，最有机械拆装逻辑。
   * false：组内再按序号细分时间窗，形成“组整体先、组内逐件再动”的两级层次。
   */
  strict?: boolean;
  /**
   * 时间窗重叠倍数（缺省 1，上限 {@link EXPLOSION_OVERLAP_MAX}）。
   *
   * 1 = 每件（每组）只占自己的时间槽，前一件停下后下一件才起步——严格但一顿一顿；
   * >1 = 每件窗口拉长、与相邻件重叠，形成连续波次：外壳先让位，内部件接力跟上，
   * 同一时刻有两三件在动，观感是“拆装流水线”而不是“逐件跳帧”。
   *
   * 起点会线性重映射，保证**第一件从 0 起步、最后一件仍在 1 结束**——否则窗口变长后
   * 末件在进度 100% 时只走完一半（`motionProgress` 会按拉长后的窗口算）。
   */
  overlap?: number;
}

/** 重叠倍数上限：再高就变成“几乎同时散开”，失去由外到内的次序感。 */
export const EXPLOSION_OVERLAP_MAX = 4;

export interface ResolvedPartMotion {
  id: string;
  group: string;
  /** 归一化移动方向。 */
  direction: Vector3;
  /** 播放窗口 0..1。 */
  start: number;
  end: number;
  distance: number;
}

function configuredDirection(direction: [number, number, number]) {
  const vec = new Vector3(...direction);
  return vec.lengthSq() > 0 ? vec.normalize() : null;
}

function groupOf(part: DevicePartConfig) {
  return part.group ?? `__single:${part.id}`;
}

function closestToCenter(parts: DevicePartConfig[]) {
  // level 越小越接近“外壳/整机”，越大越接近“零件/深层”，用于缺省排序。
  return Math.min(...parts.map(part => part.level));
}

export function buildGroupedMotions(parts: DevicePartConfig[], options: GroupedExplosionOptions = {}): ResolvedPartMotion[] {
  const groups = new Map<string, DevicePartConfig[]>();
  for (const part of parts) {
    const key = groupOf(part);
    const bucket = groups.get(key);
    if (bucket) bucket.push(part);
    else groups.set(key, [part]);
  }

  const ordered = [...groups.entries()].sort((a, b) => {
    const keyA = closestToCenter(a[1]);
    const keyB = closestToCenter(b[1]);
    // outside-in：外壳/表层(level 小)先动，内层(level 大)后动 → 升序。
    // inside-out：内层先抽出 → 降序。
    return options.order === 'inside-out' ? keyB - keyA : keyA - keyB;
  });

  const total = ordered.length;
  const motions: ResolvedPartMotion[] = [];

  ordered.forEach(([, groupParts], groupIndex) => {
    const groupStart = groupIndex / total;
    const groupEnd = (groupIndex + 1) / total;
    const inner = Math.max(1, groupParts.length);

    if (options.strict !== false) {
      // 默认：整组刚体 —— 同组共享方向、距离与窗口，观感为“一个子装配整体让位”。
      const configured = groupParts.map(part => configuredDirection(part.direction)).find(direction => direction !== null);
      const groupDirection = configured
        ?? new Vector3(0, 0, 1).applyAxisAngle(new Vector3(0, 1, 0), groupIndex * 2 * Math.PI / total);
      const groupDistance = Math.max(0.4, ...groupParts.map(part => part.distance || 1.6 + indexOf(groupParts, part) * 0.45));

      for (const part of groupParts) {
        motions.push({
          id: part.id,
          group: groupOf(part),
          direction: groupDirection.normalize(),
          start: groupStart,
          end: groupEnd,
          distance: groupDistance,
        });
      }
      return;
    }

    // strict=false：组整体让位后，组内部件再按各自方向/距离在细分窗口内逐步展开。
    groupParts.forEach((part, index) => {
      const rawDirection = configuredDirection(part.direction);
      const direction = rawDirection
        ?? new Vector3(0, 0, 1).applyAxisAngle(new Vector3(0, 1, 0), groupIndex * 2 * Math.PI / total + index * Math.PI / inner);
      motions.push({
        id: part.id,
        group: groupOf(part),
        direction: direction.normalize(),
        start: groupStart + (index / inner) / total,
        end: groupStart + ((index + 1) / inner) / total,
        distance: part.distance > 0 ? part.distance : 1.6 + index * 0.45,
      });
    });
  });

  return applyOverlap(motions, options.overlap ?? 1);
}

/**
 * 把“首尾相接”的时间窗拉长成相互重叠的波次（见 {@link GroupedExplosionOptions.overlap}）。
 *
 * 只在 overlap>1 时生效，且 overlap=1 时原样返回——旧行为逐位不变（`explosionLayout.test.ts`
 * 里那条“窗口均分”的断言依赖这一点）。起点按最大起点线性重映射，末件仍收在 1。
 */
function applyOverlap(motions: ResolvedPartMotion[], overlap: number) {
  const scale = Number.isFinite(overlap) ? Math.min(EXPLOSION_OVERLAP_MAX, Math.max(1, overlap)) : 1;
  if (scale <= 1 || motions.length === 0) return motions;

  const span = Math.max(WINDOW_EPSILON, motions.reduce((max, motion) => Math.max(max, motion.start), 0));
  return motions.map(motion => {
    const length = Math.min(1, (motion.end - motion.start) * scale);
    const start = (motion.start / span) * Math.max(0, 1 - length);
    return { ...motion, start, end: start + length };
  });
}

function indexOf(parts: DevicePartConfig[], target: DevicePartConfig) {
  return parts.findIndex(part => part.id === target.id);
}

export function motionFor(motions: ResolvedPartMotion[], partId: string) {
  return motions.find(motion => motion.id === partId) ?? null;
}

const WINDOW_EPSILON = 1e-6;

/** 部件在某个拆解进度下的移动量（0..1 窗口内缓动）。 */
export function motionProgress(motion: ResolvedPartMotion, progress: number) {
  const clamped = Math.min(1, Math.max(0, progress));
  if (motion.end - motion.start <= WINDOW_EPSILON) return clamped >= motion.start ? 1 : 0;
  const local = (clamped - motion.start) / (motion.end - motion.start);
  return Math.min(1, Math.max(0, local));
}

/** 从原始位置出发计算目标位置（不读取任何全局状态，可反复调用）。 */
export function explodedPositionFrom(
  origin: { x: number; y: number; z: number },
  motion: ResolvedPartMotion,
  progress: number,
  /** 挂点世界旋转：把 motion.direction（世界坐标）换算到挂点局部坐标。 */
  rotation?: Quaternion | null,
) {
  const local = motionProgress(motion, progress);
  if (local <= 0 || motion.distance <= 0) {
    return new Vector3(origin.x, origin.y, origin.z);
  }
  const direction = rotation ? motion.direction.clone().applyQuaternion(rotation.clone().invert()) : motion.direction;
  const eased = local * local * (3 - 2 * local);
  return new Vector3(origin.x, origin.y, origin.z).addScaledVector(direction, motion.distance * eased);
}

/* ------------------------------------------------------------------ *
 * B 阶段：装箱排布（explosionLayout 的“终态整洁”部分）
 *
 * 思路（见 docs/project/EXPLOSION-PLANNING.md §四）：按部件包围盒划分互不相交
 * 的网格单元，每个部件居中放进自己的格子。因为 cellX/cellY/cellZ ≥ 任意部件
 * 尺寸 × PADDING，而格子互不相交，所以落位后任意两个部件的包围盒必然不相交。
 * 这是纯数学保证，不依赖具体模型。
 * ------------------------------------------------------------------ */

/** 格子内边距系数：格子边长 = 最大部件尺寸 × 该系数。 */
export const PACKING_PADDING = 1.15;

const IDENTITY = new Quaternion();

export interface PackingEntry {
  id: string;
  /** 部件装配状态下的**世界**包围盒。 */
  box: Box3;
  /**
   * 部件挂点相对世界坐标系的旋转。网格偏移量本身是世界坐标差，直接加到
   * `object.position` 上时会被父级旋转再次旋转，因此需要用它换回局部坐标。
   * 缺省视为无旋转（单位四元数）。
   */
  rotation?: Quaternion;
}

export interface PackingLayout {
  /** 每个部件的**世界**坐标偏移量（格心 − 部件中心）。 */
  worldOffsets: Map<string, Vector3>;
  /** 每个部件的**局部**坐标偏移量，可直接加到挂点 `position` 上。 */
  offsets: Map<string, Vector3>;
  cell: Vector3;
  columns: number;
  rows: number;
}

/**
 * 选择网格列数：在 1..N 中挑一个让"整体宽高比"最接近正方形的列数，
 * 避免细长条排布导致相机必须退得很远。
 */
function chooseColumns(entries: PackingEntry[], cell: Vector3) {
  const total = entries.length;
  let best = 1;
  let bestRatio = Infinity;
  for (let columns = 1; columns <= total; columns += 1) {
    const rows = Math.ceil(total / columns);
    const width = columns * Math.max(cell.x, cell.z);
    const height = rows * cell.y;
    const ratio = Math.max(width, height) / Math.max(1e-6, Math.min(width, height));
    // 平局时保留更小的列数（先到先得），避免浮点噪声改变排布。
    if (ratio < bestRatio - 1e-9) {
      bestRatio = ratio;
      best = columns;
    }
  }
  return best;
}

/** 装配状态下所有部件包围盒的并集；无有效包围盒时返回 null。 */
export function unionOfBoxes(entries: Array<{ box: Box3 }>) {
  const union = new Box3();
  for (const entry of entries) {
    if (!entry.box.isEmpty()) union.union(entry.box);
  }
  return union.isEmpty() ? null : union;
}

/**
 * 计算终态装箱偏移量。返回 null 表示没有可排布的部件（调用方应跳过 B 阶段）。
 */
export function createPackingLayout(entries: PackingEntry[], padding = PACKING_PADDING): PackingLayout | null {
  const usable = entries.filter(entry => !entry.box.isEmpty());
  if (!usable.length) return null;

  const size = new Vector3();
  const cell = new Vector3();
  for (const entry of usable) {
    entry.box.getSize(size);
    cell.max(size);
  }
  cell.multiplyScalar(padding);

  const columns = chooseColumns(usable, cell);
  const rows = Math.ceil(usable.length / columns);
  const union = unionOfBoxes(usable)!;
  const center = union.getCenter(new Vector3());

  const worldOffsets = new Map<string, Vector3>();
  const offsets = new Map<string, Vector3>();
  const partCenter = new Vector3();
  const inverse = new Quaternion();

  usable.forEach((entry, index) => {
    const col = index % columns;
    const row = Math.floor(index / columns);
    const cellCenter = new Vector3(
      center.x + (col - (columns - 1) / 2) * cell.x,
      center.y + ((rows - 1) / 2 - row) * cell.y,
      center.z,
    );
    const world = cellCenter.sub(entry.box.getCenter(partCenter));
    worldOffsets.set(entry.id, world);
    inverse.copy(entry.rotation ?? IDENTITY).invert();
    offsets.set(entry.id, world.clone().applyQuaternion(inverse));
  });

  return { worldOffsets, offsets, cell, columns, rows };
}

/** 把世界坐标偏移换算成某个旋转下的局部偏移（供单挂点快速换算）。 */
export function worldOffsetToLocal(world: Vector3, rotation: Quaternion) {
  return world.clone().applyQuaternion(rotation.clone().invert());
}
