import { Box3, Quaternion, Vector3, type Mesh, type Object3D } from 'three';
import type { DevicePartConfig } from '../../config/schema';
import {
  buildGroupedMotions,
  createPackingLayout,
  explodedPositionFrom,
  unionOfBoxes,
  type PackingLayout,
  type ResolvedPartMotion,
} from '../disassembly/explosionLayout';
import { calculateExplodedPosition } from '../disassembly/explosionMath';
import type { DeviceView } from './useDeviceView';

export interface DeviceSceneState {
  selectedPartId: string | null;
  isolatedPartId: string | null;
  hiddenPartIds: string[];
  explode: number;
  view: DeviceView;
  rotate: boolean;
  reset: number;
  detailsOpen: boolean;
}

export interface DevicePartRuntime {
  id: string;
  config: DevicePartConfig;
  roots: Object3D[];
  meshes: Mesh[];
  origins: Vector3[];
  originalVisibility: boolean[];
  bounds: Box3 | null;
  /**
   * 每个挂点相对世界坐标系的旋转。世界坐标的拆除方向/装箱偏移要换算到挂点
   * 局部坐标后才能加到 `position` 上（FBX 部件挂点常带 −90° X 预旋转）。
   */
  rootRotations?: Array<Quaternion | null>;
}

/**
 * 模型水平居中之后，把每个部件的世界包围盒同步平移同样的量。
 *
 * 为什么必须同步：`registerDeviceParts` 是在**模型挂到场景之前**算的 `runtime.bounds`，
 * 那时模型还带着交付文件里的原始坐标（武高所坐标系下设备在 x≈-154 m）。而装箱布局与
 * A 阶段起吊终态都按**世界坐标**使用这份包围盒，若不同步平移，`fit()` 会把相机对到
 * 154 m 外的空处——表现就是"一拉拆解滑杆整屏空白"（真实 FBX 模型才会触发，
 * 早期程序化模型本来就在原点，所以一直没暴露）。
 */
export function shiftPartBounds(parts: Map<string, DevicePartRuntime>, delta: Vector3) {
  if (delta.lengthSq() === 0) return;
  for (const runtime of parts.values()) runtime.bounds?.translate(delta);
}

type VisibilityState = Pick<DeviceSceneState, 'isolatedPartId' | 'hiddenPartIds'>;

export function isRuntimePartVisible(part: { id: string }, state: VisibilityState) {
  // 隔离优先：只显示被隔离的部件；否则按部件级的“隐藏”开关过滤（默认全部显示）。
  if (state.isolatedPartId !== null) return part.id === state.isolatedPartId;
  return !state.hiddenPartIds.includes(part.id);
}

/** 判断是否使用 grouped 编排（部件标注了 group，或设备显式开启）。 */
export function shouldUseGroupedExplosion(device: { explosion?: { mode?: string }; parts: Array<{ group?: string }> }) {
  return device.explosion?.mode === 'grouped' || device.parts.some(part => part.group != null);
}

/**
 * 由设备配置预计算一次 grouped 编排（避免每帧重建）。返回 null 表示无需编排。
 */
export function buildExplosionMotions(
  device: {
    explosion?: { mode?: string; order?: 'outside-in' | 'inside-out'; duration?: number; overlap?: number };
    parts: DevicePartConfig[];
  },
): ResolvedPartMotion[] | null {
  if (!shouldUseGroupedExplosion(device)) return null;
  return buildGroupedMotions(device.parts, {
    order: device.explosion?.order ?? 'outside-in',
    strict: false,
    overlap: device.explosion?.overlap ?? 1,
  });
}

function rotationAt(runtime: DevicePartRuntime, index: number) {
  return runtime.rootRotations?.[index] ?? null;
}

/**
 * B 阶段：按部件装配包围盒计算装箱布局（每部件一个互不相交的格子）。
 *
 * 需要在装配状态下调用——此时 `bounds` 才是真实的装配包围盒。
 * 返回 null 表示没有可排布的部件。
 */
export function buildPackingLayout(parts: Map<string, DevicePartRuntime>): PackingLayout | null {
  const entries = [...parts.values()]
    .filter(runtime => runtime.bounds && !runtime.bounds.isEmpty())
    .map(runtime => ({
      id: runtime.id,
      box: runtime.bounds as Box3,
      // 同部件各挂点旋转一致（同一次导入），取第一个即可。
      rotation: rotationAt(runtime, 0) ?? undefined,
    }));
  return createPackingLayout(entries);
}

/**
 * 展开终态的包围盒：每个部件包围盒按其在**世界**坐标下的装箱偏移平移后求并集。
 * 相机据此取景，保证 B 阶段部件不会跑出画面。
 */
export function terminalBounds(parts: Map<string, DevicePartRuntime>, layout: PackingLayout | null) {
  if (!layout) {
    const union = unionOfBoxes([...parts.values()].map(runtime => ({ box: runtime.bounds ?? new Box3() })));
    return union;
  }
  const moved = [];
  for (const runtime of parts.values()) {
    if (!runtime.bounds || runtime.bounds.isEmpty()) continue;
    const offset = layout.worldOffsets.get(runtime.id);
    if (!offset) continue;
    moved.push({ box: runtime.bounds.clone().translate(offset) });
  }
  return unionOfBoxes(moved);
}

/**
 * A 阶段（只起吊、不装箱）的终态包围盒：每个部件按它在世界坐标下的**起吊方向 × 距离**平移后求并集。
 *
 * 为什么需要它：`explosion.layout: "none"` 时不做装箱，部件只会沿各自方向让位，
 * 若沿用装配包围盒取景，吊起来的部件会飞出画面（尤其"塔式设备逐级上吊"这种编排，
 * 终态高度可能是装配高度的 1.5~2 倍）。方向优先取编排计算出的 motion（grouped 模式可能
 * 给未配置方向的部件自动分配扇形方向），没有 motion 时退回部件自身的配置方向。
 */
export function liftTerminalBounds(
  parts: Map<string, DevicePartRuntime>,
  motions: ResolvedPartMotion[] | null = null,
) {
  const motionById = new Map(motions?.map(motion => [motion.id, motion]) ?? []);
  const moved: Array<{ box: Box3 }> = [];
  for (const runtime of parts.values()) {
    if (!runtime.bounds || runtime.bounds.isEmpty()) continue;
    const motion = motionById.get(runtime.id);
    const direction = motion
      ? motion.direction.clone()
      : new Vector3(...runtime.config.direction);
    const distance = motion ? motion.distance : runtime.config.distance;
    if (direction.lengthSq() === 0 || !(distance > 0)) {
      moved.push({ box: runtime.bounds });
      continue;
    }
    moved.push({ box: runtime.bounds.clone().translate(direction.normalize().multiplyScalar(distance)) });
  }
  return unionOfBoxes(moved);
}

export function applyRuntimeState(
  parts: Map<string, DevicePartRuntime>,
  state: Pick<DeviceSceneState, 'selectedPartId' | 'isolatedPartId' | 'hiddenPartIds' | 'explode'>,
  motions: ResolvedPartMotion[] | null = null,
  layout: PackingLayout | null = null,
) {
  const effectiveState = state.isolatedPartId !== null && !parts.has(state.isolatedPartId)
    ? { ...state, isolatedPartId: null }
    : state;
  const motionById = new Map(motions?.map(motion => [motion.id, motion]) ?? []);
  for (const runtime of parts.values()) {
    const visible = isRuntimePartVisible({ id: runtime.id }, effectiveState);
    const worldOffset = layout?.offsets.get(runtime.id) ?? null;
    runtime.roots.forEach((root, index) => {
      root.visible = visible && (runtime.originalVisibility[index] ?? true);
      const origin = runtime.origins[index];
      if (!origin) return;
      const rotation = rotationAt(runtime, index);
      const motion = motionById.get(runtime.id);
      if (motion) {
        root.position.copy(explodedPositionFrom(origin, motion, effectiveState.explode, rotation));
        return;
      }
      root.position.copy(calculateExplodedPosition(origin, runtime.config, effectiveState.explode, {
        // B 阶段偏移量是**世界**坐标差，按各挂点自身旋转换算成局部量后加入。
        layoutOffset: worldOffset,
        rotation,
      }));
    });
  }
}

/** 同向部件等距化时的缺省层间留白（世界单位）。 */
export const EXPLOSION_STACK_CLEARANCE = 0.9;

function extentAlong(bounds: Box3, direction: Vector3) {
  let low = Number.POSITIVE_INFINITY;
  let high = Number.NEGATIVE_INFINITY;
  for (let index = 0; index < 8; index += 1) {
    const corner = new Vector3(
      index & 1 ? bounds.max.x : bounds.min.x,
      index & 2 ? bounds.max.y : bounds.min.y,
      index & 4 ? bounds.max.z : bounds.min.z,
    );
    const projection = corner.dot(direction);
    low = Math.min(low, projection);
    high = Math.max(high, projection);
  }
  return Number.isFinite(low) ? high - low : 0;
}

/**
 * 把「同一个方向的一摞部件」在展开态排成等距。
 *
 * 配置里的 `distance` 是按各自需要手写的，而模型的装配间距并不均匀（发生器塔节
 * 1.81–2.16 m、厚度 2.45–3.40 m），于是展开后每层留白忽大忽小、上下两端的塔节还会
 * 蹭在一起。这里按运行时包围盒量出每件沿该方向的真实厚度，取中位数 + 留白作为节距，
 * 再反算每件需要的距离：**配置只写方向，间距交给算法**。
 *
 * 最下面那件保留配置里的抬升量（鼓形塔节该离底座多远是造型决定），其余按节距往上排；
 * 时间窗（由外到内的波次）完全不动。
 */
export function equalizeStackMotions(
  parts: Map<string, DevicePartRuntime>,
  motions: ResolvedPartMotion[] | null,
  clearance = EXPLOSION_STACK_CLEARANCE,
): ResolvedPartMotion[] | null {
  if (!motions || motions.length < 3) return motions;

  const buckets = new Map<string, ResolvedPartMotion[]>();
  motions.forEach(motion => {
    if (motion.distance <= 0 || motion.direction.lengthSq() === 0) return;
    const key = motion.direction.toArray().map(value => value.toFixed(3)).join(',');
    const bucket = buckets.get(key);
    if (bucket) bucket.push(motion);
    else buckets.set(key, [motion]);
  });

  const adjusted = new Map<string, number>();
  for (const bucket of buckets.values()) {
    // 少于三件时"等距化"没有意义（两件之间只有一个间距）。
    if (bucket.length < 3) continue;
    const direction = bucket[0]!.direction.clone().normalize();
    const entries = bucket
      .map(motion => {
        const runtime = parts.get(motion.id);
        const origin = runtime?.origins[0] ?? runtime?.roots[0]?.position;
        const span = runtime?.bounds ? extentAlong(runtime.bounds, direction) : 0;
        return { motion, projection: origin ? origin.dot(direction) : null, extent: span };
      })
      .filter((entry): entry is { motion: ResolvedPartMotion; projection: number; extent: number } => entry.projection !== null)
      .sort((left, right) => left.projection - right.projection);
    if (entries.length < 3) continue;

    const extents = entries.map(entry => entry.extent).filter(value => value > 0).sort((left, right) => left - right);
    const medianExtent = extents.length ? extents[Math.floor(extents.length / 2)]! : 0;
    const span = entries[entries.length - 1]!.projection - entries[0]!.projection;
    const assembledPitch = span / (entries.length - 1);
    const pitch = Math.max(medianExtent + clearance, assembledPitch);
    const base = entries[0]!.projection + entries[0]!.motion.distance;

    entries.forEach((entry, index) => {
      adjusted.set(entry.motion.id, Math.max(0, base + index * pitch - entry.projection));
    });
  }

  if (adjusted.size === 0) return motions;
  return motions.map(motion => {
    const distance = adjusted.get(motion.id);
    if (distance === undefined || Math.abs(distance - motion.distance) < 1e-4) return motion;
    return { ...motion, distance };
  });
}

export interface ExplosionSpring {
  value: number;
  velocity: number;
}

/** 拆解弹簧刚度/阻尼比。阻尼比略小于 1 ⇒ 末段有一点点回弹，这正是"机械到位"的手感。 */
export const EXPLOSION_SPRING_STIFFNESS = 46;
export const EXPLOSION_SPRING_RATIO = 0.82;

export function createExplosionSpring(): ExplosionSpring {
  return { value: 0, velocity: 0 };
}

/**
 * 单帧推进拆解进度。
 *
 * 原来是 `MathUtils.damp(current, target, 9, delta)`：指数逼近、永远差一点点，起步和收尾都是
 * "匀速糊过去"的观感，而且每个部件的窗口边界也被这条曲线一起糊掉。
 * 换成弹簧后起步有加速、末段有一点点回弹，"逐级升起"的层次才看得清。
 * 隔离部件时直接归零（与原行为一致：隔离取景期间不显示拆解位移）。
 */
export function stepExplosionSpring(
  spring: ExplosionSpring,
  target: number,
  isolatedPartId: string | null,
  delta: number,
) {
  if (isolatedPartId !== null) {
    spring.value = 0;
    spring.velocity = 0;
    return 0;
  }
  const step = Math.min(0.033, Math.max(0, delta));
  const damping = 2 * Math.sqrt(EXPLOSION_SPRING_STIFFNESS) * EXPLOSION_SPRING_RATIO;
  // 显式欧拉在低帧率（手机掉到 30fps 以下）会发散：大时间步拆成两半积分。
  const substeps = step > 0.016 ? 2 : 1;
  const dt = step / substeps;
  for (let index = 0; index < substeps; index += 1) {
    const acceleration = EXPLOSION_SPRING_STIFFNESS * (target - spring.value) - damping * spring.velocity;
    spring.velocity += acceleration * dt;
    spring.value += spring.velocity * dt;
  }
  if (Math.abs(spring.value - target) < 0.0006 && Math.abs(spring.velocity) < 0.02) {
    spring.value = target;
    spring.velocity = 0;
  }
  return spring.value;
}
